#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    vector<int> stack;
    for (int i = 0; i < n; i++) {
        if (stack.empty() || a[i] < a[stack.back()]) stack.push_back(i);
    }
    int best = 0;
    for (int j = n - 1; j >= 0; j--) {
        while (!stack.empty() && a[stack.back()] <= a[j]) {
            best = max(best, j - stack.back());
            stack.pop_back();
        }
    }
    cout << best << "\n";

    return 0;
}

